// Node: Workflow Config   ([SPL] HubSpot -> Simpro (Real Time))
// Single source of truth for this workflow: edit values HERE only.
// Also turns the HubSpot webhook payload into the list of records to look at. HubSpot can send SEVERAL events in one
// call, so every event is read (not just the first). Only company, contact and Site events are handled; deal events
// (quotes and jobs), deletions and anything else are ignored. If nothing is left, the run ends here on purpose.
const CONFIG = {
  // --- TEST MODE: while true, only TEST records are created in Simpro. Set to false to create everything. ---
  testOnly: true,
  // A record is a test record when its name starts with namePrefix OR its own email domain is in emailDomains (case-insensitive).
  testRecords: { namePrefix: 'HSTEST-', emailDomains: ['aniccadigital.io', 'spl.com.au'] },
  hubspotApiBase: 'https://api.hubapi.com',
  simproBaseUrl: 'https://spl.simprosuite.com/api/v1.0',
  // --- What is handled: HubSpot object, the property holding the Simpro ID, and the properties needed for Simpro ---
  types: {
    company: {
      path: 'crm/objects/2026-09/companies', assoc: 'companies', idProperty: 'simpro_customer_id', nameFields: ['name'], emailField: 'email',
      properties: ['simpro_customer_id', 'name', 'address', 'city', 'zip', 'state', 'phone', 'website', 'country', 'email', 'abn', 'billing_address', 'billing_city', 'billing_state', 'billing_postalcode', 'billing_zip', 'billing_country'],
    },
    contact: {
      path: 'crm/objects/2026-09/contacts', assoc: 'contacts', idProperty: 'simpro_contact_id', nameFields: ['firstname', 'lastname'], emailField: 'email',
      properties: ['simpro_contact_id', 'firstname', 'lastname', 'email', 'phone', 'salutation', 'department', 'jobtitle'],
    },
    site: {
      path: 'crm/objects/2026-09/0-420', assoc: '0-420', idProperty: 'simpro_site_id', nameFields: ['hs_name'], emailField: null,
      properties: ['simpro_site_id', 'hs_name', 'hs_address_1', 'hs_city', 'hs_zip', 'country', 'zone', 'hs_state_province', 'billing_address', 'billing_state', 'billing_city', 'billing_postal_code'],
    },
  },
};

const body = $input.first().json.body;
const events = Array.isArray(body) ? body : [];
const typeOf = (e) => {
  const st = String(e.subscriptionType ?? '');
  if (st.includes('deletion')) return null;                       // the record is gone
  if (e.objectTypeId === '0-420') return 'site';
  if (st.startsWith('company') || e.objectTypeId === '0-2') return 'company';
  if (st.startsWith('contact') || e.objectTypeId === '0-1') return 'contact';
  return null;                                                      // deals (quotes and jobs) and everything else
};
const seen = new Set();
const records = [];
let ignored = 0;
for (const e of events) {
  const type = typeOf(e || {});
  if (!type || e.objectId === undefined || e.objectId === null) { ignored++; continue; }
  const key = type + ':' + e.objectId;
  if (seen.has(key)) continue; // the same record twice in one call
  seen.add(key);
  records.push({ type, hsId: String(e.objectId) });
}
if (records.length === 0) return [];
$execution.customData.set('records', records.map(r => r.type + ':' + r.hsId).join(', ').slice(0, 250));
return [{ json: { ...CONFIG, records, ignored } }];

// Node: Build Record Reads   ([SPL] HubSpot -> Simpro (Real Time))
// Read the records named in the webhook from HubSpot: one batch read per record type (100 per call), with every
// property needed for Simpro, so there is no separate read per record.
const cfg = $('Workflow Config').first().json;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const requests = [];
for (const type of Object.keys(cfg.types)) {
  const ids = cfg.records.filter(r => r.type === type).map(r => r.hsId);
  chunk(ids, 100).forEach((part, n) => requests.push({
    url: cfg.hubspotApiBase + '/' + cfg.types[type].path + '/batch/read',
    body: { properties: cfg.types[type].properties, inputs: part.map(id => ({ id })) },
    meta: { type, batch: n + 1 },
  }));
}
return requests.map(r => ({ json: r }));

// Node: Prepare Records   ([SPL] HubSpot -> Simpro (Real Time))
// Real Time only CREATES: a record that already has a Simpro ID is left alone (the 30-minute sync updates it).
// While TEST MODE is on, only test records (name starts with the prefix, or own email domain is a test domain) go on.
// Nothing left = the run ends here on purpose. One state item out.
const cfg = $('Workflow Config').first().json;
const reqs = $('Build Record Reads').all(); // the requests, in the order they were sent
const rule = cfg.testRecords;
const prefix = String(rule.namePrefix).toLowerCase();
const domains = rule.emailDomains.map(d => String(d).trim().toLowerCase());

const records = [];
const counts = { inWebhook: cfg.records.length, ignoredEvents: cfg.ignored, notFound: 0, alreadyInSimpro: 0, skippedNonTest: 0 };
$input.all().forEach((item, k) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
  const meta = reqs[idx].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) { counts.notFound += reqs[idx].json.body.inputs.length; return; }
  if (r.statusCode !== 200 && r.statusCode !== 207) {
    throw new Error('HubSpot read of ' + meta.type + ' records failed (HTTP ' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300));
  }
  const t = cfg.types[meta.type];
  const found = new Set();
  for (const row of ((r.body && r.body.results) || [])) {
    found.add(String(row.id));
    const p = row.properties ?? {};
    const sid = p[t.idProperty];
    if (sid !== undefined && sid !== null && sid !== '') { counts.alreadyInSimpro++; continue; }
    if (cfg.testOnly) {
      const name = t.nameFields.map(f => p[f]).filter(Boolean).join(' ').trim().toLowerCase();
      const email = String(t.emailField ? (p[t.emailField] ?? '') : '').trim().toLowerCase();
      const domain = email.includes('@') ? email.split('@').pop() : '';
      if (!(name.startsWith(prefix) || (domain !== '' && domains.includes(domain)))) { counts.skippedNonTest++; continue; }
    }
    records.push({ type: meta.type, hsId: String(row.id), props: p });
  }
  counts.notFound += reqs[idx].json.body.inputs.filter(i => !found.has(String(i.id))).length;
});
if (records.length === 0) return []; // nothing to create
return [{ json: { records, counts } }];

// Node: Build Association Reads   ([SPL] HubSpot -> Simpro (Real Time))
// Contacts need their company, Sites their companies and contacts. One batch read per type and link (100 per call).
// Companies need none: nothing to read = a single { skip: true } item.
const cfg = $('Workflow Config').first().json;
const { records } = $('Prepare Records').first().json;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const TO = { contact: ['companies'], site: ['companies', 'contacts'] };
const requests = [];
for (const type of Object.keys(TO)) {
  const ids = records.filter(r => r.type === type).map(r => r.hsId);
  for (const to of TO[type]) {
    chunk(ids, 100).forEach((part, n) => requests.push({
      url: cfg.hubspotApiBase + '/crm/v4/associations/' + cfg.types[type].assoc + '/' + to + '/batch/read',
      body: { inputs: part.map(id => ({ id })) },
      meta: { type, to, batch: n + 1 },
    }));
  }
}
if (requests.length === 0) return [{ json: { skip: true } }];
return requests.map(r => ({ json: r }));

// Node: Build Related Reads   ([SPL] HubSpot -> Simpro (Real Time))
// Reads the Simpro ID of every related company and contact (batches of 100). No related records = { skip: true }.
const cfg = $('Workflow Config').first().json;
const reqs = $('Build Association Reads').all();
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const need = { companies: new Set(), contacts: new Set() };
$input.all().forEach((item, k) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
  const meta = reqs[idx].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return; // none of these records has links of this type
  if (r.statusCode !== 200 && r.statusCode !== 207) {
    throw new Error('HubSpot association read (' + meta.type + ' -> ' + meta.to + ') failed (HTTP ' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300));
  }
  for (const row of ((r.body && r.body.results) || [])) for (const t of (row.to ?? [])) need[meta.to].add(String(t.toObjectId));
});
const OBJ = { companies: { path: cfg.types.company.path, prop: cfg.types.company.idProperty }, contacts: { path: cfg.types.contact.path, prop: cfg.types.contact.idProperty } };
const out = [];
for (const [to, set] of Object.entries(need)) {
  chunk([...set], 100).forEach((part, n) => out.push({
    url: cfg.hubspotApiBase + '/' + OBJ[to].path + '/batch/read',
    body: { properties: [OBJ[to].prop], inputs: part.map(id => ({ id })) },
    meta: { to, batch: n + 1 },
  }));
}
if (out.length === 0) return [{ json: { skip: true } }];
return out.map(r => ({ json: r }));

// Node: Resolve Plan   ([SPL] HubSpot -> Simpro (Real Time))
// For each record to create: where to create it in Simpro, the body (same field mapping as the old
// [SPL] Upsert ... in Simpro sub-workflows), and the Simpro IDs of what it links to. A record that cannot be created
// yet because its parent is not in Simpro (a contact whose company has no Simpro ID) is listed under `skipped`,
// never created half-linked. Related records are never created here. One state item out.
const cfg = $('Workflow Config').first().json;
const { records } = $('Prepare Records').first().json;
const base = cfg.simproBaseUrl;
const blank = (v) => v === null || v === undefined || v === '' || v === 'null';
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;

// what each record is linked to in HubSpot: assoc[type][to][hubspotId] = [{ id, types:Set(typeId) }]
const assoc = { contact: { companies: {} }, site: { companies: {}, contacts: {} } };
const assocReqs = safeAll('Build Association Reads');
safeAll('Read Associations').forEach((item, k) => {
  const meta = assocReqs[idxOf(item, k)].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return;
  for (const row of ((r.body && r.body.results) || [])) {
    assoc[meta.type][meta.to][String(row.from.id)] = (row.to ?? []).map(t => ({ id: String(t.toObjectId), types: new Set((t.associationTypes ?? []).map(a => Number(a.typeId))) }));
  }
});
// the Simpro ID of each related record
const simproOf = { companies: {}, contacts: {} };
const idProp = { companies: cfg.types.company.idProperty, contacts: cfg.types.contact.idProperty };
const relReqs = safeAll('Build Related Reads');
safeAll('Read Related Objects').forEach((item, k) => {
  const meta = relReqs[idxOf(item, k)].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return;
  for (const x of ((r.body && r.body.results) || [])) {
    const v = x.properties && x.properties[idProp[meta.to]];
    if (!blank(v)) simproOf[meta.to][String(x.id)] = String(v);
  }
});
const related = (type, hsId, to, preferType) => {
  const list = ((assoc[type][to] ?? {})[hsId] ?? []).filter(t => simproOf[to][t.id] !== undefined);
  const preferred = preferType ? list.filter(t => t.types.has(preferType)) : [];
  return [...preferred, ...list.filter(t => !preferred.includes(t))].map(t => simproOf[to][t.id]);
};
const notInSimpro = (type, hsId, to) => (((assoc[type][to] ?? {})[hsId]) ?? []).filter(t => simproOf[to][t.id] === undefined).length;
const keep = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => !blank(v)));

const plan = [];
const skipped = [];
for (const rec of records) {
  const p = rec.props;
  const out = { type: rec.type, hsId: rec.hsId, name: '', createUrl: null, body: {}, links: null, warnings: [] };
  if (rec.type === 'company') {
    out.name = p.name ?? '';
    out.createUrl = base + '/companies/0/customers/companies/';
    out.body = {
      CompanyName: p.name,
      Address: { Address: p.address || '', City: p.city || '', State: p.state || '', PostalCode: p.zip || '', Country: p.country || '' },
      BillingAddress: { Address: p.billing_address || '', City: p.billing_city || '', State: p.billing_state || '', PostalCode: p.billing_zip || p.billing_postalcode || '', Country: p.billing_country || '' },
      Phone: p.phone || '', Website: p.website || '', EIN: p.abn || '',
    };
  } else if (rec.type === 'contact') {
    out.name = [p.firstname, p.lastname].filter(Boolean).join(' ');
    const customer = related('contact', rec.hsId, 'companies', 1)[0]; // the primary company first
    if (!customer) { skipped.push({ type: rec.type, hsId: rec.hsId, reason: 'its company is not in Simpro yet (no Simpro customer ID)' }); continue; }
    out.createUrl = base + '/companies/0/customers/' + customer + '/contacts/';
    out.body = { GivenName: p.firstname || '', FamilyName: p.lastname || '', Email: p.email || '', WorkPhone: p.phone || '', Title: p.salutation || '', Department: p.department || '', Position: p.jobtitle || '' };
  } else { // site
    out.name = p.hs_name ?? '';
    out.createUrl = base + '/companies/0/sites/';
    const address = keep({ Address: p.hs_address_1, City: p.hs_city, State: p.hs_state_province, PostalCode: p.hs_zip, Country: p.country });
    const billing = keep({ Address: p.billing_address, City: p.billing_city, State: p.billing_state, PostalCode: p.billing_postal_code });
    out.body = { ...keep({ Name: p.hs_name }), ...(blank(p.zone) ? {} : { Zone: Number(p.zone) }), ...(Object.keys(address).length ? { Address: address } : {}), ...(Object.keys(billing).length ? { BillingAddress: billing } : {}) };
    out.links = { customers: related('site', rec.hsId, 'companies').map(Number), primaryContact: related('site', rec.hsId, 'contacts')[0] ?? null };
    const missing = notInSimpro('site', rec.hsId, 'companies');
    if (missing) out.warnings.push(missing + ' linked company(ies) not in Simpro yet - not linked');
  }
  plan.push(out);
}
return [{ json: { records: plan, skipped } }];

// Node: Build Record Writes   ([SPL] HubSpot -> Simpro (Real Time))
// Create every planned record in Simpro (POST), throttled. Real Time only creates, it never updates.
const { records } = $('Resolve Plan').first().json;
const writes = records.map(r => ({ json: { method: 'POST', url: r.createUrl, body: r.body, meta: { type: r.type, hsId: r.hsId, kind: 'create' } } }));
if (writes.length === 0) return [{ json: { skip: true } }];
return writes;

// Node: Build ID Write-Back   ([SPL] HubSpot -> Simpro (Real Time))
// Right after records are created in Simpro, save the new Simpro IDs on the HubSpot records (one batch update per type).
// Doing this straight away is what stops a repeated webhook from creating the same record in Simpro twice.
const cfg = $('Workflow Config').first().json;
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const reqs = safeAll('Build Record Writes').filter(i => !(i.json && i.json.skip));
const byType = {};
safeAll('Write Records to Simpro').filter(i => !(i.json && i.json.skip)).forEach((item, k) => {
  const m = reqs[idxOf(item, k)].json.meta; const r = item.json ?? {};
  if ((r.statusCode === 200 || r.statusCode === 201) && r.body && r.body.ID !== undefined) {
    (byType[m.type] = byType[m.type] ?? []).push({ id: m.hsId, properties: { [cfg.types[m.type].idProperty]: String(r.body.ID) } });
  }
});
const out = [];
for (const [type, updates] of Object.entries(byType)) {
  chunk(updates, 100).forEach((part, n) => out.push({ url: cfg.hubspotApiBase + '/' + cfg.types[type].path + '/batch/update', body: { inputs: part }, meta: { type, batch: n + 1, count: part.length } }));
}
if (out.length === 0) return [{ json: { skip: true } }];
return out.map(r => ({ json: r }));

// Node: Build Site Links   ([SPL] HubSpot -> Simpro (Real Time))
// A site was just created in Simpro: link it to its customers (only those already in Simpro) and set its primary contact
// (a HubSpot contact that already has a Simpro ID; HubSpot has no single "primary" site contact, so the first one).
// One PATCH per site. No links = { skip: true }.
const cfg = $('Workflow Config').first().json;
const { records } = $('Resolve Plan').first().json;
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
const reqs = safeAll('Build Record Writes').filter(i => !(i.json && i.json.skip));
const createdSites = {};
safeAll('Write Records to Simpro').filter(i => !(i.json && i.json.skip)).forEach((item, k) => {
  const m = reqs[idxOf(item, k)].json.meta; const r = item.json ?? {};
  if (m.type === 'site' && (r.statusCode === 200 || r.statusCode === 201) && r.body && r.body.ID !== undefined) createdSites[m.hsId] = String(r.body.ID);
});
const out = [];
for (const rec of records) {
  if (rec.type !== 'site' || !createdSites[rec.hsId] || !rec.links) continue;
  const body = {};
  if (rec.links.customers.length) body.Customers = rec.links.customers;
  if (rec.links.primaryContact) body.PrimaryContact = { Contact: Number(rec.links.primaryContact) };
  if (Object.keys(body).length) out.push({ json: { method: 'PATCH', url: cfg.simproBaseUrl + '/companies/0/sites/' + createdSites[rec.hsId], body, meta: { type: 'site', hsId: rec.hsId, kind: 'siteLinks' } } });
}
if (out.length === 0) return [{ json: { skip: true } }];
return out;

// Node: Report Result   ([SPL] HubSpot -> Simpro (Real Time))
// Last step. Looks at every call of this run. If any failed, the run fails (-> error workflow) with the details; the
// records that WERE created already have their Simpro ID saved, so a repeated webhook will not create them twice.
// Otherwise returns a short summary (what was created, what was skipped and why).
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const live = (name) => safeAll(name).filter(i => !(i.json && i.json.skip));
const idxOf = (item, k) => (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
const get = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const STAGES = [
  ['Build Record Writes', 'Write Records to Simpro', 'create in Simpro'],
  ['Build ID Write-Back', 'Write IDs to HubSpot', 'save Simpro ID in HubSpot'],
  ['Build Site Links', 'Write Site Links', 'link site in Simpro'],
];
const failures = [];
const created = { company: 0, contact: 0, site: 0 };
let linked = 0;
for (const [reqNode, resNode, label] of STAGES) {
  const reqs = live(reqNode);
  live(resNode).forEach((item, k) => {
    const meta = (reqs[idxOf(item, k)] && reqs[idxOf(item, k)].json.meta) || {};
    const r = item.json ?? {};
    const who = meta.hsId ? meta.type + ' ' + meta.hsId : 'batch ' + (meta.batch ?? '?');
    if (r.error !== undefined) { failures.push(label + ' (' + who + '): ' + (typeof r.error === 'string' ? r.error : JSON.stringify(r.error)).slice(0, 200)); return; }
    if (r.statusCode === undefined || r.statusCode >= 400) { failures.push(label + ' (' + who + '): HTTP ' + r.statusCode + ' ' + JSON.stringify(r.body).slice(0, 200)); return; }
    const errs = r.body && Array.isArray(r.body.errors) ? r.body.errors : [];
    if (errs.length) { failures.push(label + ' (' + who + '): ' + errs.slice(0, 2).map(e => e.message || JSON.stringify(e)).join(' | ')); return; }
    if (meta.kind === 'create') created[meta.type]++;
    if (meta.kind === 'siteLinks') linked++;
  });
}
if (failures.length) throw new Error(failures.length + ' call(s) failed:\n' + failures.slice(0, 20).map(f => '- ' + f).join('\n'));

const prep = get('Prepare Records');
const resolved = get('Resolve Plan');
const skipped = ((resolved && resolved.skipped) || []).map(s => s.type + ' ' + s.hsId + ': ' + s.reason);
const warnings = ((resolved && resolved.records) || []).flatMap(r => (r.warnings ?? []).map(w => r.type + ' ' + r.hsId + ': ' + w));
if (skipped.length || warnings.length) $execution.customData.set('notes', [...skipped, ...warnings].join(' | ').slice(0, 250));
return [{ json: { status: 'ok', created, siteLinksSet: linked, ...(prep ? prep.counts : {}), skippedNotReady: skipped.length, skippedDetails: skipped, warnings } }];
